  function newState(loc, level, r, opts) {
    opts = opts || {}; loc = locale(loc); level = levelOf(level);
    var F = round(loc, r), slot = opts.slot == null ? SLOTS[level][r] : opts.slot % 3;
    return { loc: loc, level: level, r: r, F: F, cards: cardsFor(F, level, r, slot), right: slot, clip: null, misses: 0, show: 0, last: null, found: null, fog: false, focus: false, done: false };
  }
  function help0(st) { st.last = null; st.found = null; st.fog = false; st.focus = false; }
